#!/usr/bin/env python3
"""Extract visible CMPD rates, match POW bill candidates, and build CMPD page."""
import json,re,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parent; OUT=ROOT/'analysis_output'; STATIC=ROOT.parent/'open-data-visualization/static/nep-preview'
OCR=Path('/tmp/cmpd-vision.json'); POW=OUT/'dpwh-in-depth-data.json'; SOURCE=ROOT/'data_sources/Nationwide CMPD_compressed.pdf'

def rates():
 pages=json.loads(OCR.read_text())['pages'];out=[]
 for p in pages:
  pg=p['page']; region='NCR' if pg<=10 else 'CAR' if 12<=pg<=17 else 'Region I'
  if region=='Region I' and pg>20:continue
  words=p['words']; codes=[w for w in words if w[0]<165 and re.fullmatch(r'M[A-Z0-9]{1,3}\.\d{4}',w[4].replace('ł','1'))]
  for c in codes:
   y=c[1]; desc=' '.join(w[4] for w in words if 175<w[0]<900 and abs(w[1]-y)<12)
   unit=next((w[4] for w in words if 900<w[0]<1050 and abs(w[1]-y)<12),'')
   avg=next((w[4] for w in words if w[0]>2200 and abs(w[1]-y)<13),'')
   val=re.sub(r'[^0-9.,]','',avg).replace(',','')
   try: amount=float(val)
   except: amount=None
   code=c[4].replace('ł','1')
   if desc:out.append({'code':code,'description':desc,'unit':unit,'average':amount,'region':region,'page':pg})
 # deduplicate OCR same code/page
 seen=set();return [r for r in out if not ((r['code'],r['region']) in seen or seen.add((r['code'],r['region'])))]
def norm(s):return re.sub(r'[^a-z0-9]+',' ',str(s or '').lower()).strip()
def main():
 refs=rates(); doc=json.loads(POW.read_text()); candidates=[]
 aliases=[('cement concrete pavement',r'\b(?:cement concrete pavement|concrete pavement|pccp)\b'),('asphalt concrete',r'\b(?:asphalt concrete|hot laid asphalt|bituminous concrete)\b'),('aggregate subbase',r'\b(?:aggregate subbase|subbase course)\b'),('aggregate base course',r'\b(?:aggregate base course|base course)\b'),('common borrow',r'\bcommon borrow\b'),('selected borrow',r'\bselected borrow\b'),('reinforcing steel',r'\b(?:reinforcing steel|deformed bars|reinforcing bars)\b'),('portland cement',r'\bportland cement\b'),('ready mix concrete',r'\b(?:ready mix concrete|ready mixed concrete)\b'),('concrete hollow blocks',r'\b(?:concrete hollow block|chb)\b'),('fine aggregate sand',r'\b(?:fine aggregate|concrete sand)\b'),('gravel',r'\bgravel\b')]
 for project in doc['projects']:
  for d in project.get('documents',[]):
   if d.get('kind')!='pow':continue
   for row in d.get('rows',[]):
    desc=row.get('description',''); u=norm(row.get('unit')); txt=norm(desc)
    for label,pat in aliases:
     if re.search(pat,txt):
      unit=('sq.m' if u in ('sq m','sqm','m2') else 'cu.m' if u in ('cu m','cum','m3') else 'kg' if u in ('kg','kgs') else 'm' if u in ('m','lin m','linear m') else row.get('unit') or '—')
      candidates.append({'material':label,'description':desc,'itemCode':row.get('itemCode'),'unit':unit,'unitCost':row.get('calculatedUnitCostPesos') or row.get('printedUnitCostPesos'),'amount':row.get('amountPesos'),'quantity':row.get('quantity'),'project':project.get('name'),'code':project.get('code'),'office':project.get('office'),'region':project.get('region'),'powUrl':d.get('url'),'page':row.get('sourcePage')})
 data={'source':SOURCE.name,'referencePeriod':'1st Semester CY 2026','coverage':'Supplied extract includes NCR (pp. 4–10), CAR (pp. 12–17), and only pp. 19–20 of Region I.','rates':refs,'candidates':candidates}
 (OUT/'cmpd-cost-per-unit-data.json').write_text(json.dumps(data,ensure_ascii=False));(STATIC/'cmpd-cost-per-unit-data.json').write_text(json.dumps(data,ensure_ascii=False))
 page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CMPD Cost per Unit · DPWH POW bills</title><style>body{margin:0;background:#f4f7f8;color:#183643;font:16px/1.5 system-ui}header{background:#00246a;color:white;padding:24px}main{padding:24px}section{background:white;margin:18px 0;padding:20px;border:1px solid #d8e5e8;border-radius:12px}.note{color:#526c78}.controls{display:grid;gap:8px;max-width:700px}select,input,button{font:inherit;padding:9px;border:1px solid #9bb8bf;border-radius:7px}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:9px;border-bottom:1px solid #dbe3e6;vertical-align:top}.num{text-align:right;white-space:nowrap}.scroll{overflow:auto}.pill{background:#fff4cc;padding:3px 7px;border-radius:6px}a{color:#0038a8}</style></head><body><header><h1>CMPD Cost per Unit</h1><p>Compare 1st Semester CY 2026 DPWH Construction Materials Price Data with matching POW bill items.</p></header><main><section><b>Source coverage</b><p class="note">The supplied compressed PDF contains NCR pages 4–10, CAR pages 12–17, and only pages 19–20 of Region I. Region I is incomplete; other regions are absent from this copy. CMPD average prices are shown as published. POW items are text matches for review, not confirmed equivalent materials or evidence of overpricing. Check the source schedule, unit, specification, location and date before comparing.</p></section><section><h2>Choose a material</h2><div class="controls"><label>Material <select id="material"></select></label><label>Search POW matches <input id="search" placeholder="Project, item or office"></label></div><p id="summary" class="note"></p><div class="scroll"><table><thead><tr><th>Material code / description</th><th>Unit</th><th>CMPD average</th><th>POW unit cost</th><th>Project and source</th></tr></thead><tbody id="rows"></tbody></table></div></section><section><h2>Reference rates by available region</h2><div class="scroll"><table><thead><tr><th>Code</th><th>Material</th><th>Unit</th><th>Region</th><th>Average</th><th>Source page</th></tr></thead><tbody id="rates"></tbody></table></div></section><p class="note">CMPD source: <a href="../data_sources/Nationwide%20CMPD_compressed.pdf">supplied PDF</a>. Department guidance: <a href="../data_sources/do_043_s2026.pdf">DO 043, s. 2026</a>. The order sets price validation procedures; it does not itself establish CMPD material rates.</p></main><script>fetch('cmpd-cost-per-unit-data.json').then(r=>r.json()).then(d=>{const s=document.querySelector('#material'),q=document.querySelector('#search'),body=document.querySelector('#rows'),rates=document.querySelector('#rates'),summary=document.querySelector('#summary');const aliases={'common borrow':['common borrow'],'selected borrow':['selected borrow'],'aggregate subbase course':['aggregate subbase','subbase course'],'aggregate base course':['aggregate base course','base course'],'cement concrete pavement':['cement concrete pavement','pccp'],'asphalt concrete':['asphalt concrete','hot laid asphalt'],'portland cement':['portland cement'],'fine aggregate sand':['fine aggregate','concrete sand'],'concrete hollow blocks':['concrete hollow block','chb'],'reinforcing steel':['reinforcing steel','deformed bars','reinforcing bars'],'ready mix concrete':['ready mix concrete','ready mixed concrete'],'gravel':['gravel']};const termsFor=name=>{const key=name.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();return Object.entries(aliases).find(([k])=>key.includes(k))?.[1]||[key]};const mats=[...new Set(d.rates.map(x=>x.description))].filter(name=>d.candidates.some(x=>termsFor(name).some(t=>x.description.toLowerCase().includes(t)))).sort();s.innerHTML=mats.map(x=>`<option>${x}</option>`).join('');function unitKey(u){u=(u||'').toLowerCase().replace(/[²³]/g,'').replace(/\s+/g,'').replace(/\./g,'');return ({cum:'m3','cu.m':'m3','m3':'m3',sqm:'m2','sq.m':'m2','m2':'m2',kg:'kg',m:'m',ltr:'l','l':'l',gal:'gal',bag:'bag',ea:'each',each:'each'})[u]||u}function draw(){const name=s.value,rr=d.rates.filter(x=>x.description===name),code=rr[0]?.code,terms=termsFor(name),refUnits=new Set(rr.map(x=>unitKey(x.unit)).filter(x=>x&&x!=='none'));const found=d.candidates.filter(x=>terms.some(t=>x.description.toLowerCase().includes(t))&&(!refUnits.size||refUnits.has(unitKey(x.unit)))&&(!q.value||[x.project,x.description,x.office].join(' ').toLowerCase().includes(q.value.toLowerCase())));summary.textContent=`${rr[0]?.description||name} · ${rr[0]?.unit||'unit unavailable'} · ${found.length} text matched POW rows. Material code ${code||'—'}.`;
body.innerHTML=found.map(x=>{const sourceRegion=x.region==='NCR'?'NCR':x.region==='CAR'?'CAR':/^Region I\b/i.test(x.region||'')?'Region I':'';const rate=rr.find(r=>r.region===sourceRegion&&r.unit.toLowerCase()===({ 'cu.m':'cum','sq.m':'sqm','kg':'kg','m':'m','l':'ltr'}[x.unit.toLowerCase()]||x.unit.toLowerCase()));return `<tr><td>${x.itemCode||''}<small>${x.description}</small></td><td>${x.unit}</td><td>${rate?.average==null?'No comparable regional rate':`₱${rate.average.toLocaleString('en-PH',{maximumFractionDigits:2})}`}<small>${rate?`${rate.region} · CMPD p.${rate.page}`:'Region/unit not available in supplied extract'}</small></td><td>${x.unitCost==null?'—':'₱'+Number(x.unitCost).toLocaleString('en-PH',{maximumFractionDigits:2})}</td><td>${x.project}<small>${x.office} · ${x.region} · POW p.${x.page} · <a href="${x.powUrl}#page=${x.page}" target="_blank">source ↗</a></small></td></tr>`}).join('')||'<tr><td colspan="5">No text matches.</td></tr>';
rates.innerHTML=rr.map(x=>`<tr><td>${x.code}</td><td>${x.description}</td><td>${x.unit}</td><td>${x.region}</td><td>${x.average==null?'OCR review needed':'₱'+x.average.toLocaleString('en-PH',{maximumFractionDigits:2})}</td><td><a href="../data_sources/Nationwide%20CMPD_compressed.pdf#page=${x.page}" target="_blank">p.${x.page} ↗</a></td></tr>`).join('')}
s.onchange=draw;q.oninput=draw;draw()}).catch(e=>document.querySelector('main').insertAdjacentHTML('beforeend','<p>Data unavailable: '+e.message+'</p>'));</script></body></html>'''
 # use one page and one JS module via generated inline script
 for target in (OUT,STATIC,ROOT/'project_documents'):
  target.mkdir(parents=True,exist_ok=True);(target/'cmpd-cost-per-unit.html').write_text(page)
 print(json.dumps({'rates':len(refs),'powCandidates':len(candidates),'page':'cmpd-cost-per-unit.html'}))
if __name__=='__main__':main()
